package main

import "net/http"

func serveUI(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" { http.NotFound(w, r); return }
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Content-Security-Policy", "default-src 'self'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'self'; img-src 'self' data:; object-src 'none'; base-uri 'none'; frame-ancestors 'none'")
	_, _ = w.Write([]byte(neuraUI))
}

const neuraUI = `<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NEURA</title><style>
:root{color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,sans-serif;background:#05070c;color:#eef5ff}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at 50% 28%,#14254a 0,#090d18 34%,#05070c 70%);overflow-x:hidden}.app{min-height:100vh;display:grid;grid-template-rows:auto 1fr auto;padding:28px;max-width:1180px;margin:auto}.top,.activity-head{display:flex;justify-content:space-between;align-items:center;gap:12px}.brand{font-weight:800;letter-spacing:.34em;font-size:14px}.status{font-size:12px;color:#93a8c7;display:flex;gap:8px;align-items:center}.dot{width:8px;height:8px;border-radius:50%;background:#6df5c4;box-shadow:0 0 16px #6df5c4}.stage{display:grid;place-items:center;text-align:center;padding:24px 0}.entity-wrap{perspective:900px;position:relative;width:min(45vw,340px);aspect-ratio:1;margin:auto}.halo{position:absolute;inset:7%;border:1px solid #6bbcff55;border-radius:50%;box-shadow:inset 0 0 70px #458cff22,0 0 90px #2869ff25;animation:halo 7s ease-in-out infinite}.brain{position:absolute;inset:18%;transform-style:preserve-3d;animation:float 6s ease-in-out infinite;filter:drop-shadow(0 20px 35px #000b)}.lobe{position:absolute;width:62%;height:72%;top:13%;border-radius:48% 54% 46% 52%;background:radial-gradient(circle at 35% 25%,#d7f4ff 0,#68b8ff 12%,#4665d9 38%,#172050 68%,#080b22 100%);box-shadow:inset 12px 8px 20px #e7fbff44,inset -14px -10px 28px #020515aa,0 0 35px #4ca6ff44}.lobe:after{content:"";position:absolute;inset:13%;border-radius:inherit;background:repeating-radial-gradient(ellipse at 45% 45%,transparent 0 9px,#b8e7ff22 10px 12px)}.left{left:3%;transform:rotateY(15deg) rotateZ(-7deg)}.right{right:3%;transform:rotateY(-15deg) rotateZ(7deg)}.core{position:absolute;inset:39%;border-radius:50%;background:#e8fbff;box-shadow:0 0 18px #fff,0 0 55px #5ad9ff,0 0 110px #566bff;animation:pulse 2.8s ease-in-out infinite}.entity-wrap[data-state=thinking] .brain,.entity-wrap[data-state=working] .brain{animation:think 1.3s ease-in-out infinite}.entity-wrap[data-state=success] .core{background:#baffdf;box-shadow:0 0 22px #fff,0 0 65px #55ffc2}.entity-wrap[data-state=error] .core{background:#ffb6bd;box-shadow:0 0 22px #fff,0 0 65px #ff5266}.title{font-size:clamp(26px,4vw,46px);font-weight:650;letter-spacing:-.035em}.subtitle{color:#8fa3c1;margin:8px auto 0;max-width:600px;line-height:1.5}.composer{width:min(760px,100%);margin:20px auto 0;display:flex;gap:10px;padding:8px;border:1px solid #91bfff2b;background:#0c1322dd;border-radius:20px;box-shadow:0 18px 55px #0008,inset 0 1px #ffffff0d;backdrop-filter:blur(18px)}input{flex:1;border:0;outline:0;background:transparent;color:#f4f8ff;padding:14px 16px;font-size:16px;min-width:0}button{border:0;border-radius:14px;padding:0 20px;background:linear-gradient(135deg,#78d9ff,#7774ff);color:#07101d;font-weight:800;cursor:pointer}button:disabled{opacity:.45;cursor:wait}.activity{width:min(760px,100%);margin:14px auto 0;padding:16px 18px;border:1px solid #91bfff24;border-radius:18px;background:#09111fdd;text-align:left;box-shadow:inset 0 1px #ffffff0a}.activity[hidden]{display:none}.activity-state{font-size:11px;letter-spacing:.1em;font-weight:800;color:#86bfff}.activity-title{font-size:15px;font-weight:700;margin-top:5px}.activity-detail{font-size:12px;color:#8093af;margin-top:5px;line-height:1.45}.spinner{width:18px;height:18px;border:2px solid #ffffff22;border-top-color:#78d9ff;border-radius:50%;animation:spin .8s linear infinite}.result{width:min(760px,100%);margin:12px auto 0;padding:16px 18px;border-radius:18px;text-align:left;font-size:14px;line-height:1.55;white-space:pre-wrap;overflow-wrap:anywhere;background:#09111f99;border:1px solid #ffffff0b}.result:empty{display:none}.result.success{border-color:#5bdbad44}.result.error{border-color:#ff6e7f55;background:#2a1018aa}.result-title{display:block;font-size:11px;letter-spacing:.09em;margin-bottom:7px;color:#8fa3c1}.panels{width:min(760px,100%);margin:14px auto 0;display:grid;grid-template-columns:1fr 1fr;gap:12px}.panel{padding:14px;border:1px solid #91bfff20;border-radius:18px;background:#09111fbb;text-align:left}.panel-head{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:10px}.panel strong{font-size:12px;letter-spacing:.06em}.task-list{display:grid;gap:8px}.task{display:flex;justify-content:space-between;gap:10px;align-items:center;padding:9px 10px;border:1px solid #ffffff0c;border-radius:12px;background:#0d1728}.task-main{min-width:0}.task-id,.memory-text{font-size:12px;font-weight:650;overflow:hidden;text-overflow:ellipsis}.task-meta,.memory-meta{font-size:10px;color:#778aa8;margin-top:4px}.badge{display:inline-block;margin-left:6px;padding:2px 6px;border-radius:999px;background:#263550;color:#b9c9df;font-size:9px}.task-actions{display:flex;gap:5px}.mini{min-height:30px;padding:0 9px;border-radius:9px;font-size:10px}.secondary{background:#18243a;color:#b7c9e4;border:1px solid #ffffff10}.memory-search{display:flex;gap:6px;margin-bottom:8px}.memory-search input{padding:8px 10px;border:1px solid #ffffff12;border-radius:10px;background:#0d1728;font-size:12px}.empty{padding:8px;color:#667995;font-size:11px}.foot{display:flex;justify-content:center;gap:18px;color:#64738b;font-size:11px;padding-top:20px}@keyframes float{50%{transform:translateY(-10px) rotateY(5deg)}}@keyframes halo{50%{transform:scale(1.04);opacity:.72}}@keyframes pulse{50%{transform:scale(1.16)}}@keyframes think{25%{transform:rotateY(8deg) translateY(-7px)}75%{transform:rotateY(-8deg) translateY(3px)}}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:720px){.app{padding:18px 14px}.entity-wrap{width:min(68vw,280px)}.panels{grid-template-columns:1fr}.composer{position:sticky;bottom:10px;z-index:5;border-radius:17px}.composer button{padding:0 15px}.task{align-items:flex-start;flex-direction:column}.task-actions{width:100%}.foot{gap:9px;flex-wrap:wrap}.activity,.result{padding:14px}.top{position:relative;z-index:6}}
</style></head><body><main class="app"><header class="top"><div class="brand">NEURA</div><div class="status"><span class="dot"></span><span id="online">connessione…</span></div></header><section class="stage"><div><div class="entity-wrap" id="entity" data-state="idle"><div class="halo"></div><div class="brain"><div class="lobe left"></div><div class="lobe right"></div><div class="core"></div></div></div><div class="title">Come posso aiutarti?</div><p class="subtitle">Dimmi l'obiettivo. NEURA mostra cosa sta facendo e ti restituisce un risultato verificabile.</p><form class="composer" id="form"><input id="goal" autocomplete="off" placeholder="Chiedi qualcosa a NEURA…" aria-label="Richiesta"><button id="send">Invia</button></form><section class="activity" id="activity" hidden aria-live="polite"><div class="activity-head"><div><div class="activity-state" id="activityState">PENSO</div><div class="activity-title" id="activityTitle">Capisco la richiesta</div><div class="activity-detail" id="activityDetail">Preparo il percorso più sicuro per completarla.</div></div><div class="spinner" id="spinner"></div></div></section><div class="result" id="result" aria-live="polite"></div><div class="panels"><section class="panel"><div class="panel-head"><strong>RECOVERY TASK</strong><button type="button" class="mini secondary" id="refreshTasks">Aggiorna</button></div><div class="task-list" id="tasks"><div class="empty">Nessun task da mostrare.</div></div></section><section class="panel"><div class="panel-head"><strong>MEMORIA ATTIVA</strong></div><form class="memory-search" id="memoryForm"><input id="memoryQuery" autocomplete="off" placeholder="Cerca memoria…"><button class="mini">Cerca</button></form><div class="task-list" id="memories"><div class="empty">Memoria non ancora caricata.</div></div></section></div></div></section><footer class="foot"><span>LOCAL FIRST</span><span>AZIONI VERIFICATE</span><span>ZERO API OBBLIGATORIE</span></footer></main><script>
const e=document.getElementById('entity'),o=document.getElementById('online'),r=document.getElementById('result'),f=document.getElementById('form'),g=document.getElementById('goal'),send=document.getElementById('send'),activity=document.getElementById('activity'),as=document.getElementById('activityState'),at=document.getElementById('activityTitle'),ad=document.getElementById('activityDetail'),spinner=document.getElementById('spinner'),t=document.getElementById('tasks'),refresh=document.getElementById('refreshTasks'),mf=document.getElementById('memoryForm'),mq=document.getElementById('memoryQuery'),ml=document.getElementById('memories');
const esc=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
function lifecycle(state,title,detail){e.dataset.state=state;activity.hidden=state==='idle';as.textContent=state==='thinking'?'PENSO':state==='working'?'LAVORO':state==='success'?'COMPLETATO':'ATTENZIONE';at.textContent=title;ad.textContent=detail||'';spinner.hidden=state==='success'||state==='error';send.disabled=state==='thinking'||state==='working';g.setAttribute('aria-busy',send.disabled?'true':'false')}
function showResult(kind,title,text){r.className='result '+kind;r.innerHTML='<span class="result-title">'+esc(title)+'</span>'+esc(text||'Nessun dettaglio restituito.')}
function friendlyError(j,status){if(j&&j.error)return j.error;if(j&&j.status==='blocked')return 'NEURA ha bloccato l’azione perché richiede un controllo prima di procedere.';if(status===503)return 'Il componente richiesto non è disponibile in questo momento.';return 'Non sono riuscito a completare la richiesta. Riprova o controlla il dettaglio del task.'}
async function status(){try{const x=await fetch('/status');if(!x.ok)throw 0;const j=await x.json();o.textContent='online · '+j.version;e.dataset.state='idle'}catch(_){o.textContent='offline';lifecycle('error','NEURA non raggiungibile','Avvia NEURA e riprova. I dati locali restano invariati.')}}
async function loadMemory(q=''){try{const x=await fetch('/memory?q='+encodeURIComponent(q)+'&limit=4'),j=await x.json();if(!x.ok)throw new Error(j.error||'Memoria non disponibile');const items=j.items||[];ml.innerHTML=items.length?items.map(x=>'<div class="task" data-memory-id="'+esc(x.id)+'"><div class="task-main"><div class="memory-text">'+esc(x.text)+'</div><div class="memory-meta">'+esc(x.type||'legacy')+' · '+esc(x.provenance||'sconosciuta')+'</div></div>'+(x.supersedes?'<div class="task-actions"><button type="button" class="mini secondary" data-memory-history>Storico</button></div>':'')+'</div>').join(''):'<div class="empty">Nessuna memoria rilevante.</div>'}catch(err){ml.innerHTML='<div class="empty">'+esc(err.message)+'</div>'}}
async function loadTasks(){try{const x=await fetch('/tasks?limit=4'),j=await x.json();if(!x.ok)throw new Error(j.error||'Task non disponibili');const items=j.items||[];t.innerHTML=items.length?items.map(x=>{let actions='';if(x.state==='blocked')actions='<button type="button" class="mini" data-action="retry">Riprova sicuro</button>';if(x.state==='manual_review')actions='<button type="button" class="mini secondary" data-action="repeat">Ripeti</button><button type="button" class="mini" data-action="verified">Verificato</button>';return '<div class="task" data-id="'+esc(x.id)+'" data-generation="'+x.generation+'"><div class="task-main"><div class="task-id">'+esc(x.id)+' <span class="badge">'+esc(x.state)+'</span></div><div class="task-meta">step '+(x.next_step||0)+'/'+((x.plan&&x.plan.steps||[]).length)+(x.last_error?' · '+esc(x.last_error):'')+'</div></div><div class="task-actions">'+actions+'</div></div>'}).join(''):'<div class="empty">Nessun task da recuperare.</div>'}catch(err){t.innerHTML='<div class="empty">'+esc(err.message)+'</div>'}}
f.addEventListener('submit',async ev=>{ev.preventDefault();const goal=g.value.trim();if(!goal||send.disabled)return;lifecycle('thinking','Capisco la richiesta','Valuto obiettivo, contesto e percorso sicuro.');r.textContent='';const workTimer=setTimeout(()=>lifecycle('working','Eseguo e verifico','Sto completando i passaggi necessari e controllo il risultato.'),450);try{const x=await fetch('/command',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({goal})}),j=await x.json();clearTimeout(workTimer);if(!x.ok)throw Object.assign(new Error(friendlyError(j,x.status)),{payload:j});const text=j.answer||j.summary||j.message||(j.status?'Stato: '+j.status:JSON.stringify(j,null,2));lifecycle('success','Richiesta completata','Il risultato è pronto qui sotto.');showResult('success','RISULTATO',text)}catch(err){clearTimeout(workTimer);lifecycle('error','Non ho completato la richiesta','Nessuna azione nascosta: leggi il motivo e correggi o riprova.');showResult('error','COSA È SUCCESSO',err.message)}finally{await Promise.all([loadTasks(),loadMemory(mq.value.trim())]);send.disabled=false;g.setAttribute('aria-busy','false')}});
t.addEventListener('click',async ev=>{const b=ev.target.closest('button[data-action]');if(!b)return;const row=b.closest('.task'),id=row.dataset.id,generation=Number(row.dataset.generation),action=b.dataset.action;if((action==='repeat'||action==='verified')&&!confirm(action==='verified'?'Confermi che l’effetto è già avvenuto ed è stato verificato?':'Confermi che vuoi rendere il task nuovamente eseguibile?'))return;lifecycle('working','Recupero il task','Applico la transizione sicura senza ripetere mutazioni alla cieca.');try{const resolve=action!=='retry',x=await fetch('/tasks/'+encodeURIComponent(id)+(resolve?'/resolve':'/retry'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(resolve?{generation,effect_verified:action==='verified'}:{generation})}),j=await x.json();if(!x.ok)throw new Error(j.error||'Recovery fallita');lifecycle('success','Task aggiornato','La recovery è stata registrata.');showResult('success','RECOVERY','Task '+id+' aggiornato in sicurezza.')}catch(err){lifecycle('error','Recovery non completata','Il task è rimasto protetto.');showResult('error','RECOVERY',err.message)}finally{await loadTasks()}});
mf.addEventListener('submit',ev=>{ev.preventDefault();loadMemory(mq.value.trim())});ml.addEventListener('click',async ev=>{const b=ev.target.closest('button[data-memory-history]');if(!b)return;const id=b.closest('[data-memory-id]').dataset.memoryId;lifecycle('working','Recupero lo storico','Ricostruisco la linea temporale della memoria.');try{const x=await fetch('/memory/history?id='+encodeURIComponent(id)),j=await x.json();if(!x.ok)throw new Error(j.error||'Storico non disponibile');lifecycle('success','Storico pronto','Puoi leggere le versioni qui sotto.');showResult('success','STORICO MEMORIA',(j.items||[]).map((m,i)=>(i+1)+'. '+m.text+' ['+(m.type||'legacy')+']').join('\n'))}catch(err){lifecycle('error','Storico non disponibile','La memoria corrente non è stata modificata.');showResult('error','MEMORIA',err.message)}});refresh.addEventListener('click',loadTasks);status();loadTasks();loadMemory();
</script></body></html>`
